        assert!(!sqlx::query_scalar::<_,bool>(sqlx::AssertSqlSafe(legacy_invoice.as_str())).bind("foreign").bind("field-invoice-billing-key").fetch_one(&mut *tx).await.unwrap());
        assert!(sqlx::query_scalar::<_,bool>(sqlx::AssertSqlSafe(projected_invoice.as_str())).bind("company").bind("field-invoice-billing-key").fetch_one(&mut *tx).await.unwrap());
        assert!(!sqlx::query_scalar::<_,bool>(sqlx::AssertSqlSafe(projected_invoice.as_str())).bind("foreign").bind("field-invoice-billing-key").fetch_one(&mut *tx).await.unwrap());field_join.require_current(&mut tx).await.unwrap();
